#!/usr/bin/env node
/**
 * Import the Metagenics catalog into this Medusa backend.
 *
 *   node scripts/import-metagenics.mjs            # all 229 products
 *   node scripts/import-metagenics.mjs --sample   # 3 products to try it out
 *
 * Source: the storefront's own derived catalog (../src/lib/data/metagenics/catalog.json,
 * generated by ../scripts/import-metagenics.mjs from the shopStore collection) and the
 * 229 main images in ../public/products. shopStore is not needed at import time.
 *
 * Compared with shopStore's importer this also stores, as metadata:
 *   - per variant: size, flavor, subscription offers (1/2/3 months), availability
 *   - per product: collected rating summary, product line, form, bundle flag,
 *     description blocks, supplement facts, directions, storage, cautions, warnings, FAQ
 * Variants that were out of stock in the source start with stock 0, the rest with 99.
 *
 * It also sets up the store for the storefront checkout: one USD region for the US and China,
 * carriers FedEx/DHL (US) and SF/JD (China) as shipping options (free when the items total ≥ $30),
 * and promo codes FRESH10/FARM20/OCT26DAILY.
 *
 * Re-runs are safe: existing products (matched by handle + external_id) are reused and
 * their stock is never reset. All writes go through the Medusa Admin API.
 * Requires the backend to be running (pnpm start:local).
 */
import assert from "node:assert/strict"
import { readFile, writeFile } from "node:fs/promises"
import path from "node:path"
import { fileURLToPath } from "node:url"

const backendDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const repoDir = path.resolve(backendDir, "..")
const BACKEND = process.env.MEDUSA_BACKEND_URL ?? "http://localhost:9000"
const SOURCE_DATE = "2026-10-31"
const sample = process.argv.includes("--sample")

const readJson = async (file) => JSON.parse(await readFile(file, "utf8"))
const catalog = await readJson(path.join(repoDir, "src/lib/data/metagenics/catalog.json"))
const config = await readJson(path.join(backendDir, ".local/config.json"))

// ---------- API clients ----------
async function request(route, { body, method, headers }) {
  const response = await fetch(`${BACKEND}${route}`, {
    method: method ?? (body === undefined ? "GET" : "POST"),
    headers: { ...(body instanceof FormData ? {} : { "content-type": "application/json" }), ...headers },
    body: body === undefined ? undefined : body instanceof FormData ? body : JSON.stringify(body),
    signal: AbortSignal.timeout(120000),
  })
  const value = await response.json()
  if (!response.ok) throw new Error(`${route}: HTTP ${response.status}: ${value.message || value.type}`)
  return value
}

const login = await request("/auth/user/emailpass", { body: { email: config.adminEmail, password: config.adminPassword } })
const admin = (route, body, method) => request(route, { body, method, headers: { authorization: `Bearer ${login.token}` } })

// ---------- checks on the source ----------
const products = sample
  ? catalog.products.filter((p) => ["magnesium-glycinate", "ultrameal-advanced-protein", "gut-health-bundle"].includes(p.slug))
  : catalog.products
const skus = catalog.products.flatMap((p) => p.variants.map((v) => v.sku))
assert.equal(new Set(skus).size, skus.length, "Duplicate SKU in catalog")
for (const p of catalog.products) for (const v of p.variants) assert(v.sku && v.price > 0, `Invalid variant in ${p.slug}`)

// ---------- store setup: US region, warehouse, demo shipping, collection, categories ----------
const {
  stores: [store],
} = await admin("/admin/stores")

// One USD region for the demo: the storefront's English checkout ships to the US, the Chinese one to China.
const COUNTRIES = ["us", "cn"]
const { regions } = await admin("/admin/regions")
let region = regions.find((r) => r.countries.some((c) => c.iso_2 === "us"))
if (region && !COUNTRIES.every((code) => region.countries.some((c) => c.iso_2 === code)))
  ({ region } = await admin(`/admin/regions/${region.id}`, { countries: COUNTRIES }))
if (!region)
  ({ region } = await admin("/admin/regions", {
    name: "United States & China (USD demo)",
    currency_code: "usd",
    countries: COUNTRIES,
    payment_providers: ["pp_system_default"],
    automatic_taxes: false,
    metadata: { purpose: "metagenics_demo", source_date: SOURCE_DATE },
  }))
assert.equal(region.currency_code, "usd", "Existing US region must use USD")

const { stock_locations } = await admin("/admin/stock-locations?limit=100")
let location = stock_locations.find((l) => l.name === "Metagenics Demo Warehouse")
if (!location)
  ({ stock_location: location } = await admin("/admin/stock-locations", {
    name: "Metagenics Demo Warehouse",
    address: { address_1: "Local demo", country_code: "us" },
    metadata: { purpose: "metagenics_demo" },
  }))
await admin(`/admin/stock-locations/${location.id}/sales-channels`, { add: [store.default_sales_channel_id] })
await admin(`/admin/stock-locations/${location.id}/fulfillment-providers`, { add: ["manual_manual"] })

const {
  shipping_profiles: [profile],
} = await admin("/admin/shipping-profiles")
const fulfillmentSets = async () =>
  (await admin(`/admin/stock-locations/${location.id}?fields=*fulfillment_sets,*fulfillment_sets.service_zones`)).stock_location
    .fulfillment_sets ?? []
let set = (await fulfillmentSets()).find((f) => f.name === "Metagenics Demo Delivery")
if (!set) {
  await admin(`/admin/stock-locations/${location.id}/fulfillment-sets`, { name: "Metagenics Demo Delivery", type: "shipping" })
  set = (await fulfillmentSets()).find((f) => f.name === "Metagenics Demo Delivery")
}
/** Carriers shown in the storefront checkout (src/lib/checkout/regions.ts); matched by type code `carrier-<id>`. */
const CARRIERS = {
  us: { zone: "United States Demo", options: [{ id: "fedex", name: "FedEx", amount: 32 }, { id: "dhl", name: "DHL", amount: 15 }] },
  // the storefront shows ¥12 / ¥8; the demo region bills in USD (rate 7.1)
  cn: { zone: "China Demo", options: [{ id: "sf", name: "SF Express", amount: 1.69 }, { id: "jd", name: "JD Logistics", amount: 1.127 }] },
}
/**
 * "Free shipping on orders over $30" (homepage banner): every carrier costs 0 once the cart's
 * item_total — the items after discounts, without shipping — reaches $30.
 */
const FREE_SHIPPING_RULE = { attribute: "item_total", operator: "gte", value: 30 }
const freeShippingPrice = { currency_code: "usd", amount: 0, rules: [FREE_SHIPPING_RULE] }
for (const [country, { zone: zoneName, options }] of Object.entries(CARRIERS)) {
  let zone = set.service_zones?.find((z) => z.name === zoneName)
  if (!zone) {
    const { fulfillment_set } = await admin(`/admin/fulfillment-sets/${set.id}/service-zones?fields=*service_zones`, {
      name: zoneName,
      geo_zones: [{ type: "country", country_code: country }],
    })
    zone = fulfillment_set.service_zones.find((z) => z.name === zoneName)
  }
  const { shipping_options } = await admin(
    `/admin/shipping-options?service_zone_id=${zone.id}&fields=id,name,*type,*prices,*prices.price_rules`,
  )
  for (const o of options) {
    const existing = shipping_options.find((x) => x.type?.code === `carrier-${o.id}`)
    if (existing) {
      // older databases: add the free-shipping price if it is missing
      const hasFree = existing.prices?.some((p) => p.price_rules?.some((r) => r.attribute === FREE_SHIPPING_RULE.attribute))
      if (!hasFree) {
        const base = existing.prices.find((p) => !p.price_rules?.length)
        await admin(`/admin/shipping-options/${existing.id}`, {
          prices: [{ id: base.id, currency_code: "usd", amount: base.amount }, freeShippingPrice],
        })
      }
      continue
    }
    await admin("/admin/shipping-options", {
      name: o.name,
      price_type: "flat",
      provider_id: "manual_manual",
      service_zone_id: zone.id,
      shipping_profile_id: profile.id,
      type: { label: o.name, description: "Demo carrier (not a real quote)", code: `carrier-${o.id}` },
      prices: [{ currency_code: "usd", amount: o.amount }, freeShippingPrice],
      rules: [
        { attribute: "enabled_in_store", value: "true", operator: "eq" },
        { attribute: "is_return", value: "false", operator: "eq" },
      ],
      metadata: { purpose: "demo_only", carrier: o.id },
    })
  }
}

// promo codes used by the storefront checkout
const { promotions } = await admin("/admin/promotions?limit=100")
// OCT26DAILY: "20% off" on the homepage banners — the whole order
for (const [code, percent] of [["FRESH10", 10], ["FARM20", 20], ["OCT26DAILY", 20]]) {
  if (promotions.some((p) => p.code === code)) continue
  await admin("/admin/promotions", {
    code,
    type: "standard",
    status: "active",
    is_automatic: false,
    application_method: { type: "percentage", target_type: "order", value: percent, allocation: "across" },
  })
}

await admin(`/admin/stores/${store.id}`, {
  default_region_id: region.id,
  default_location_id: location.id,
  supported_currencies: store.supported_currencies.map((c) => ({ currency_code: c.currency_code, is_default: c.currency_code === "usd" })),
})

const { collections } = await admin("/admin/collections?limit=100")
let collection = collections.find((c) => c.handle === "metagenics")
if (!collection) ({ collection } = await admin("/admin/collections", { title: "Metagenics", handle: "metagenics" }))

const { product_categories } = await admin("/admin/product-categories?limit=100")
const categoryIds = new Map()
for (const c of catalog.categories) {
  const handle = `metagenics-${c.slug}`
  let category = product_categories.find((x) => x.handle === handle)
  if (!category)
    ({ product_category: category } = await admin("/admin/product-categories", {
      name: c.name,
      handle,
      is_active: true,
      is_internal: false,
      metadata: { brand: "Metagenics", slug: c.slug, source_url: c.sourceUrl },
    }))
  categoryIds.set(c.slug, category.id)
}

// ---------- products ----------
/** Medusa options: "Size" and/or "Flavor" when the source has them, otherwise a single "Bundle"/"Default" option. */
function optionsFor(p) {
  const sizes = [...new Set(p.variants.map((v) => v.size).filter(Boolean))]
  const flavors = [...new Set(p.variants.map((v) => v.flavor).filter(Boolean))]
  const options = []
  if (sizes.length && p.variants.every((v) => v.size)) options.push({ title: "Size", values: sizes })
  if (flavors.length && p.variants.every((v) => v.flavor)) options.push({ title: "Flavor", values: flavors })
  const combos = p.variants.map((v) => options.map((o) => (o.title === "Size" ? v.size : v.flavor)).join("|"))
  if (!options.length || new Set(combos).size !== combos.length) {
    return { options: [{ title: p.isBundle ? "Bundle" : "Default", values: p.variants.map((v) => v.label) }], pick: (v) => ({ [p.isBundle ? "Bundle" : "Default"]: v.label }) }
  }
  return {
    options,
    pick: (v) => Object.fromEntries(options.map((o) => [o.title, o.title === "Size" ? v.size : v.flavor])),
  }
}

const report = { importedAt: new Date().toISOString(), mode: sample ? "sample" : "all", created: 0, reused: 0, products: [] }

for (const [index, p] of products.entries()) {
  const externalId = `metagenics:${p.slug}`
  let {
    products: [product],
  } = await admin(`/admin/products?handle=${encodeURIComponent(p.slug)}&fields=*variants,*variants.inventory_items`)

  if (product) {
    assert.equal(product.external_id, externalId, `Handle ${p.slug} belongs to another product; refused to overwrite`)
    report.reused++
  } else {
    let image
    if (p.image) {
      const bytes = await readFile(path.join(repoDir, "public", p.image))
      const form = new FormData()
      form.append("files", new Blob([bytes], { type: "image/png" }), path.basename(p.image))
      ;({
        files: [image],
      } = await admin("/admin/uploads", form))
    }
    const { options, pick } = optionsFor(p)
    ;({ product } = await admin("/admin/products?fields=*variants,*variants.inventory_items", {
      title: p.name,
      subtitle: p.subtitle ?? null,
      description: p.summary ?? null,
      handle: p.slug,
      external_id: externalId,
      status: "published",
      collection_id: collection.id,
      thumbnail: image?.url,
      images: image ? [{ url: image.url }] : [],
      shipping_profile_id: profile.id,
      categories: p.categories.map((slug) => ({ id: categoryIds.get(slug) })),
      sales_channels: [{ id: store.default_sales_channel_id }],
      options,
      variants: p.variants.map((v, i) => ({
        title: v.label,
        sku: v.sku,
        variant_rank: i,
        manage_inventory: true,
        allow_backorder: false,
        options: pick(v),
        prices: [{ currency_code: "usd", amount: v.price }],
        metadata: {
          size: v.size ?? null,
          flavor: v.flavor ?? null,
          subscriptions: v.subscriptions,
          source_available: v.available,
        },
      })),
      metadata: {
        brand: "Metagenics",
        source_url: p.sourceUrl,
        source_date: SOURCE_DATE,
        health_categories: p.categories,
        product_line: p.productLine ?? null,
        form: p.form,
        is_bundle: p.isBundle,
        rating: p.rating ?? null,
        content: p.description,
        supplement_facts: p.supplementFacts ?? null,
        directions: p.directions ?? null,
        storage: p.storage ?? null,
        cautions: p.cautions ?? null,
        warnings: p.warnings ?? null,
        faq: p.faq,
        related: p.related,
      },
    }))
    report.created++
  }

  // stock: 99 per variant (0 if it was out of stock in the source); never reset existing levels
  for (const variant of product.variants) {
    const source = p.variants.find((v) => v.sku === variant.sku)
    const inventoryId = variant.inventory_items?.[0]?.inventory_item_id
    assert(inventoryId, `No inventory item: ${variant.sku}`)
    const { inventory_levels } = await admin(`/admin/inventory-items/${inventoryId}/location-levels?location_id=${location.id}`)
    if (!inventory_levels.length)
      await admin(`/admin/inventory-items/${inventoryId}/location-levels`, {
        location_id: location.id,
        stocked_quantity: source?.available === false ? 0 : 99,
      })
  }
  report.products.push({ id: product.id, handle: p.slug, variants: product.variants.length })
  console.log(`${index + 1}/${products.length} ${p.slug} (${product.variants.length} variants)`)
}

// ---------- check through the Store API (what the storefront will use) ----------
const { api_keys } = await admin("/admin/api-keys?type=publishable")
const key = api_keys.find((k) => !k.revoked_at)
assert(key, "No publishable API key")
const storeApi = (route, body) => request(route, { body, headers: { "x-publishable-api-key": key.token } })
const {
  products: [check],
} = await storeApi(
  `/store/products?region_id=${region.id}&handle=magnesium-glycinate&fields=*variants.calculated_price,+variants.inventory_quantity,+variants.metadata,+metadata`,
)
assert(check, "Sample product not visible in the store")
const variant = check.variants.find((v) => v.sku === "MAGG240") ?? check.variants[0]
const { cart } = await storeApi("/store/carts", { region_id: region.id })
const { cart: updated } = await storeApi(`/store/carts/${cart.id}/line-items`, { variant_id: variant.id, quantity: 1 })
report.validation = {
  storeVisible: true,
  sku: variant.sku,
  price: variant.calculated_price?.calculated_amount,
  inventory: variant.inventory_quantity,
  subscriptions: variant.metadata?.subscriptions?.length ?? 0,
  rating: check.metadata?.rating ?? null,
  cartAdd: updated.items[0]?.quantity === 1,
}
await writeFile(path.join(backendDir, ".local/import-report.json"), JSON.stringify(report, null, 2) + "\n")
console.log(JSON.stringify({ created: report.created, reused: report.reused, count: report.products.length, validation: report.validation }))
